#ifndef GUARD_STRATA_ART_H
#define GUARD_STRATA_ART_H

#include "sprite.h"
#include "strata_map.h" // Strata_GetMapEra

// Era-specific art that isn't part of a map's tileset: battle backgrounds and the grass
// field effects. Data generated by tools/strata/gen_tilesets.py (gen_era_tiles.py).

// The palette (3 banks of 16 colours) to load for a battle environment:
// the era variant of `stock` if the current map's era has one, else `stock`.
const void *Strata_GetBattleEnvironmentPalette(u32 environment, const void *stock);

// The battle environment's background tiles and entry-animation tiles: the era's own
// (its undergrowth instead of grass, on the grass environments) or `stock`.
const void *Strata_GetBattleEnvironmentTiles(u32 environment, const void *stock);
const void *Strata_GetBattleEnvironmentAnimTiles(u32 environment, const void *stock);

// The era variant of a field-effect sprite palette (same tag), or `palette` itself.
const struct SpritePalette *Strata_GetFieldEffectPalette(const struct SpritePalette *palette);

// The frames of a field-effect object (FLDEFFOBJ_TALL_GRASS, FLDEFFOBJ_LONG_GRASS) in the
// current era: its undergrowth instead of grass, or `stock`. Same frame size and count.
const struct SpriteFrameImage *Strata_GetFieldEffectImages(u32 fieldEffectObject, const struct SpriteFrameImage *stock);

#endif // GUARD_STRATA_ART_H
